INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('18727147-0b1d-463f-a650-d85e3000493d', 'b2b2b2b2-3030-4000-8000-000000000002', 16, 'Dia 16 — Autocompaixão', 'Semana 3: Reconstruir', '{"pch": "Como um pai se compadece dos filhos\u2026 Seja gentil consigo mesmo como Deus \u00e9 com voc\u00ea.", "verse": "Sl 103,13", "lectio": "Leia Sl 103,8-14. Deus conhece nossa fragilidade.", "practice": "Hoje, trate-se como trataria seu melhor amigo.", "question": "Como voc\u00ea se trata quando falha?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('247ec458-de31-4b8d-a22c-15f26a0969e7', 'b2b2b2b2-3030-4000-8000-000000000002', 17, 'Dia 17 — Limites', 'Semana 3: Reconstruir', '{"pch": "Seja o vosso sim, sim; e o vosso n\u00e3o, n\u00e3o\u2026 Limites saud\u00e1veis protegem o que Deus cura.", "verse": "Mt 5,37", "lectio": "Leia Mt 5,33-37. Clareza nas palavras.", "practice": "Defina 1 limite que voc\u00ea vai estabelecer esta semana.", "question": "Onde voc\u00ea precisa dizer n\u00e3o para proteger sua paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('78f04225-0188-4a5f-9641-566f2ca54937', 'b2b2b2b2-3030-4000-8000-000000000002', 18, 'Dia 18 — Gratidão', 'Semana 3: Reconstruir', '{"pch": "Transformaste o meu pranto em dan\u00e7a\u2026 A gratid\u00e3o muda o foco da dor para a gra\u00e7a.", "verse": "Sl 30,11", "lectio": "Leia Sl 30. De lamento a louvor.", "practice": "Escreva 5 coisas boas que existem por causa de algo dif\u00edcil.", "question": "O que de bom nasceu de algo que te machucou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('e13ea0a4-693c-4ed8-87d4-f83b33fbcc98', 'b2b2b2b2-3030-4000-8000-000000000002', 19, 'Dia 19 — Força', 'Semana 3: Reconstruir', '{"pch": "Os que esperam no Senhor renovar\u00e3o as suas for\u00e7as\u2026 A for\u00e7a vem da espera, n\u00e3o da pressa.", "verse": "Is 40,31", "lectio": "Leia Is 40,28-31. O Deus eterno n\u00e3o se cansa.", "practice": "Fa\u00e7a algo que recarregue sua energia emocional hoje.", "question": "De onde voc\u00ea tira for\u00e7a quando tudo parece demais?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f8455191-ac40-4c0c-bec1-b628b7d118f1', 'b2b2b2b2-3030-4000-8000-000000000002', 20, 'Dia 20 — Vulnerabilidade', 'Semana 3: Reconstruir', '{"pch": "Temos esse tesouro em vasos de barro\u2026 Sua fragilidade n\u00e3o \u00e9 fraqueza \u2014 \u00e9 transpar\u00eancia.", "verse": "2Cor 4,7", "lectio": "Leia 2Cor 4,7-12. Poder na fragilidade.", "practice": "Compartilhe algo verdadeiro com algu\u00e9m de confian\u00e7a.", "question": "Com quem voc\u00ea pode ser vulner\u00e1vel?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('be9d5286-0a3e-4dbf-aa8d-f41237d8df95', 'b2b2b2b2-3030-4000-8000-000000000002', 21, 'Dia 21 — Esperança', 'Semana 3: Reconstruir', '{"pch": "O Deus da esperan\u00e7a vos encha de alegria e paz\u2026 A esperan\u00e7a \u00e9 uma pessoa, n\u00e3o um sentimento.", "verse": "Rm 15,13", "lectio": "Leia Rm 15,13. Transbordar de esperan\u00e7a.", "practice": "Escreva 3 coisas que ainda espera ver acontecer.", "question": "Em que voc\u00ea ainda espera?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('58a2a723-a8a3-44cf-9acb-7d799ed70a2d', 'b2b2b2b2-3030-4000-8000-000000000002', 22, 'Dia 22 — Recomeço', 'Semana 4: Integrar', '{"pch": "As miseric\u00f3rdias do Senhor renovam-se cada manh\u00e3\u2026 Cada dia \u00e9 um novo come\u00e7o.", "verse": "Lm 3,22-23", "lectio": "Leia Lm 3,19-26. Esperan\u00e7a no meio da ru\u00edna.", "practice": "Comece algo novo hoje \u2014 mesmo pequeno.", "question": "O que voc\u00ea gostaria de recome\u00e7ar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c20d1e17-3623-4448-99a6-1c8146565526', 'b2b2b2b2-3030-4000-8000-000000000002', 23, 'Dia 23 — Identidade restaurada', 'Semana 4: Integrar', '{"pch": "Eu te chamei pelo teu nome, tu \u00e9s meu\u2026 Sua identidade n\u00e3o est\u00e1 na dor \u2014 est\u00e1 em quem te criou.", "verse": "Is 43,1", "lectio": "Leia Is 43,1-7. Precioso aos olhos de Deus.", "practice": "Escreva: Eu sou mais do que aconteceu comigo porque _____", "question": "Como voc\u00ea se define al\u00e9m da sua dor?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('79b7e0cb-da66-4450-8acc-fc19c16c5348', 'b2b2b2b2-3030-4000-8000-000000000002', 24, 'Dia 24 — Propósito na dor', 'Semana 4: Integrar', '{"pch": "Todas as coisas cooperam para o bem\u2026 Sua dor tem prop\u00f3sito, mesmo quando n\u00e3o parece.", "verse": "Rm 8,28", "lectio": "Leia Rm 8,28-30. O plano de Deus.", "practice": "Escreva como sua dor pode servir a outra pessoa.", "question": "Que sentido voc\u00ea encontra na sua hist\u00f3ria?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6352aa56-67fc-470f-a23a-9bf0366b1caf', 'b2b2b2b2-3030-4000-8000-000000000002', 25, 'Dia 25 — Cicatrizes', 'Semana 4: Integrar', '{"pch": "Jesus mostrou suas cicatrizes\u2026 Elas n\u00e3o desapareceram \u2014 se tornaram testemunho.", "verse": "Jo 20,27", "lectio": "Leia Jo 20,24-29. Tom\u00e9 tocou as feridas.", "practice": "Agrade\u00e7a por uma cicatriz. Ela prova que voc\u00ea sobreviveu.", "question": "Que cicatrizes suas contam uma hist\u00f3ria de supera\u00e7\u00e3o?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d74e36fd-1550-42bf-a471-75f292b882a0', 'b2b2b2b2-3030-4000-8000-000000000002', 26, 'Dia 26 — Alegria', 'Semana 4: Integrar', '{"pch": "A alegria do Senhor \u00e9 a vossa for\u00e7a\u2026 A alegria n\u00e3o nega a dor \u2014 coexiste com ela.", "verse": "Ne 8,10", "lectio": "Leia Ne 8,9-12. Chorar e celebrar no mesmo dia.", "practice": "Fa\u00e7a algo que te d\u00ea alegria pura hoje.", "question": "O que te d\u00e1 alegria verdadeira?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('78ece41c-115b-42c7-b9ab-f4e888bd44c3', 'b2b2b2b2-3030-4000-8000-000000000002', 27, 'Dia 27 — Conexão', 'Semana 4: Integrar', '{"pch": "Levai as cargas uns dos outros\u2026 Cura n\u00e3o acontece no isolamento.", "verse": "Gl 6,2", "lectio": "Leia Gl 6,1-5. Comunidade na restaura\u00e7\u00e3o.", "practice": "Ligue para algu\u00e9m. Diga: preciso de voc\u00ea.", "question": "Quem voc\u00ea precisa ao seu lado neste momento?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('514f473e-a51b-4076-b0de-75285f981850', 'b2b2b2b2-3030-4000-8000-000000000002', 28, 'Dia 28 — Paz', 'Semana 4: Integrar', '{"pch": "A minha paz vos dou\u2026 n\u00e3o como o mundo a d\u00e1. Paz n\u00e3o \u00e9 aus\u00eancia de conflito \u2014 \u00e9 presen\u00e7a de Deus.", "verse": "Jo 14,27", "lectio": "Leia Jo 14,25-31. O Consolador vem.", "practice": "Identifique o ladr\u00e3o de paz. Entregue-o em ora\u00e7\u00e3o.", "question": "O que te rouba a paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('275c740d-e9b2-456f-84d3-7e2d2e764762', 'b2b2b2b2-3030-4000-8000-000000000002', 29, 'Dia 29 — Testemunho', 'Semana 4: Integrar', '{"pch": "Tirou-me do po\u00e7o\u2026 e p\u00f4s nos meus l\u00e1bios um c\u00e2ntico novo. Sua hist\u00f3ria \u00e9 seu testemunho.", "verse": "Sl 40,2-3", "lectio": "Leia Sl 40,1-5. Da espera ao louvor.", "practice": "Escreva seu testemunho em 5 frases.", "question": "O que voc\u00ea diria a algu\u00e9m que est\u00e1 onde voc\u00ea estava?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('a80d565d-c6d9-4f86-b941-cec6e83d1841', 'b2b2b2b2-3030-4000-8000-000000000002', 30, 'Dia 30 — Inteiro', 'Semana 4: Integrar', '{"pch": "Sara os quebrantados de cora\u00e7\u00e3o\u2026 e liga-lhes as feridas. Voc\u00ea n\u00e3o est\u00e1 quebrado. Est\u00e1 sendo restaurado.", "verse": "Sl 147,3", "lectio": "Leia Sl 147,1-7. Deus conta as estrelas e sara os cora\u00e7\u00f5es.", "practice": "Releia suas reflex\u00f5es dos 30 dias. Escreva uma carta de gratid\u00e3o a si mesmo.", "question": "Quem voc\u00ea se tornou atrav\u00e9s da dor?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f75b8079-8b74-4a7d-b250-c3e7b88ced2b', 'c1c2c3d4-3030-4000-8000-000000000030', 1, 'Perceber', 'Semana 1 — Despertar', '{"pch": "A pressa revela\u2026 onde a confian\u00e7a ainda n\u00e3o chegou.", "verse": "Mt 6,25-34", "lectio": "Leia o texto lentamente. Pare na palavra que incomoda. Pergunte: por que essa palavra me toca?", "practice": "Escreva no di\u00e1rio: qual \u00e1rea da minha vida estou tentando controlar com pressa?", "question": "O que est\u00e1 te acelerando?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('986ec036-538c-4d29-9ce3-d78185c46588', 'c1c2c3d4-3030-4000-8000-000000000030', 2, 'Pausar', 'Semana 1 — Despertar', '{"pch": "Nem todo movimento \u00e9 progresso\u2026 \u00e0s vezes \u00e9 fuga.", "verse": "Sl 46,10", "lectio": "Sente-se em sil\u00eancio por 3 minutos antes de ler. Depois leia o salmo duas vezes.", "practice": "Identifique uma a\u00e7\u00e3o que voc\u00ea repete por ansiedade, n\u00e3o por necessidade.", "question": "Do que voc\u00ea est\u00e1 fugindo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8040b3ca-8cce-4c4e-8e65-840a0d18de35', 'c1c2c3d4-3030-4000-8000-000000000030', 3, 'Sentir', 'Semana 1 — Despertar', '{"pch": "Sentir n\u00e3o \u00e9 fraqueza\u2026 \u00e9 acesso.", "verse": "Sl 34,18", "lectio": "Leia o vers\u00edculo e pergunte: onde est\u00e1 essa dor em mim agora?", "practice": "Nomeie tr\u00eas emo\u00e7\u00f5es que voc\u00ea sentiu hoje, sem julgamento.", "question": "O que voc\u00ea evita sentir?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('77fca868-67b4-4f17-91cd-c74cb2546161', 'c1c2c3d4-3030-4000-8000-000000000030', 4, 'Nomear', 'Semana 1 — Despertar', '{"pch": "Aquilo que voc\u00ea n\u00e3o nomeia\u2026 te controla.", "verse": "Gn 2,19-20", "lectio": "Assim como Ad\u00e3o nomeou cada criatura, nomeie o que vive dentro de voc\u00ea.", "practice": "Escreva: qual medo, h\u00e1bito ou ferida eu ainda n\u00e3o nomeei?", "question": "O que voc\u00ea ainda n\u00e3o enfrentou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('45d795f0-f382-43ac-9a04-101bbbbd2a76', 'c1c2c3d4-3030-4000-8000-000000000030', 5, 'Aceitar', 'Semana 1 — Despertar', '{"pch": "Aceitar n\u00e3o \u00e9 desistir\u2026 \u00e9 parar de lutar contra o que j\u00e1 \u00e9.", "verse": "Rm 8,28", "lectio": "Leia e pergunte: o que Deus pode estar fazendo com aquilo que eu rejeito?", "practice": "Escreva uma coisa que voc\u00ea precisa parar de resistir.", "question": "O que voc\u00ea resiste?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
